  for(var s:input.fixedSources()){var verified=sources.require(a,new SourceReadProtocol.ReadRequirement(s.sourceVersion(),s.rightsRevision(),h.projectId(),input.snapshotId(),s.parseVersion(),null,SourceReadProtocol.Use.HISTORY,s.purpose(),text(exec,"environment"),text(exec,"region"),null));same(s.approvalRevision(),verified.selection().approvalRevision());rights.put(s.rightsRevision(),s.sourceVersion());sourcePins.add(AgentPublicationWitness.tree(verified));}
  var submission=one(db.queryForList("SELECT * FROM task_source_verifier_submission WHERE tenant_id=? AND project_id=? AND check_id=? LIMIT 2 FOR UPDATE",h.tenantId(),h.projectId(),check));var receipt=json.read(str(submission,"receipt_json"));same(json.hash(receipt),str(submission,"receipt_sha256"));same(receipt,json.read(str(row,"result_ref")));same("N05",text(receipt,"node_kind"));same(input.candidateId(),text(receipt,"candidate_id"));same(input.bodyArtifactId(),text(receipt,"target_revision"));same(input.bodyObject().sha256(),text(receipt,"target_sha256"));same(str(row,"input_sha256"),text(receipt,"input_sha256"));if(receipt.required("professional_approval").asBoolean())bad();journal(h.tenantId(),h.projectId(),str(submission,"created_by"),receipt,"task.source_verifier.review.submitted","candidate.review.recorded");
