  var ar=one(artifacts.artifact(id));same(json.hash(payload),ar.sha256());same(json.tree(ar.reference()),receipt.required("object_ref"));var b=one(artifacts.binding(id));same("TASK",b.resourceKind());same(input.taskId(),b.resourceId());same(kind.equals("findings")?schemas.schemaRef("artifacts",null):TaskSourceVerifierReviewService.COVERAGE_REF,b.schemaRef());same(kind.equals("findings")?schemas.schemaDigest("artifacts"):TaskSourceVerifierReviewService.coverageManifest(),b.schemaDocumentSha256());
  var provenance=receipt.required("provenance");same("N05",text(provenance,"node_kind"));same(json.hash(input),text(provenance,"input_sha256"));same(ar.sha256(),text(provenance,"payload_sha256"));var pins=provenance.required("independent_reads");var read=one(db.queryForList("SELECT canonical_receipt,receipt_sha256 FROM task_source_verifier_context_read WHERE tenant_id=? AND project_id=? AND run_id=? AND step_id=? AND session_id=? LIMIT 2 FOR UPDATE",input.tenantId(),input.projectId(),input.runId(),input.stepId(),text(provenance,"session_id")));same(pins,json.read(str(read,"canonical_receipt")));same(json.hash(pins),str(read,"receipt_sha256"));if(kind.equals("coverage"))same(pins,payload.required("independent_reads"));
