 private void authorizeGraph(EnterpriseAccess.Admission a,TaskSourceVerifierInput input,String id,Map<String,String> rights,List<Object> sourcePins,boolean local)throws Exception{
  resources.require(a,new PermissionProtocol.Scope(input.tenantId(),input.projectId(),"ARTIFACT",id),"artifact.read",TaskSourceVerifierReviewService.PURPOSE);var ar=one(artifacts.artifact(id));var b=one(artifacts.binding(id));same(input.tenantId(),ar.tenantId());same(input.projectId(),ar.projectId());same(ar.sha256(),ar.contentSha256());StoredObjectReferences.decode(ar.storedObject(),ar.reference());same(ar.accessSetId(),b.accessSetId());var mr=one(artifacts.manifest(ar.accessSetId()));same(b.dependencyManifestSha256(),mr.manifestSha256());var manifest=manifests.verify(mr,artifacts.members(ar.accessSetId()));var graph=lineage.require(id,manifest.members(),policy.limits());same(ar.sha256(),graph.versions().get(id).contentSha256());
  var done=new HashSet<String>();done.add(id);for(var m:manifest.members()){
   if(m.rightsRevision()!=null){String src=rights.get(m.rightsRevision());if(src==null||!graph.reachableFrom(m.upstreamVersionId()).contains(src))throw new TenantAccessException(ErrorCode.ACCESS_DENIED);}
   var sub=lineage.inspect(m.upstreamVersionId(),policy.limits());var req=new HashMap<String,ArtifactRegistryProtocol.ReadRequirement>();for(var v:sub.versions().values())if("ARTIFACT".equals(v.entityKind())){var bind=one(artifacts.binding(v.id()));var profile=one(policy.artifactProfiles().stream().filter(p->p.schemaRef().equals(bind.schemaRef())&&p.resourceKind().equals(bind.resourceKind())).toList());req.put(v.id(),new ArtifactRegistryProtocol.ReadRequirement(new PermissionProtocol.Scope(input.tenantId(),bind.projectId(),bind.resourceKind(),bind.resourceId()),profile.action(),TaskSourceVerifierReviewService.PURPOSE,profile.schemaRef(),profile.schemaDocumentSha256(),profile.artifactSchemaManifest(),policy.limits()));}
   var verified=versions.require(a,sub,TaskSourceVerifierReviewService.PURPOSE,new VersionResourceProtocol.ReadContext(SourceReadProtocol.Use.HISTORY,null),req);for(var v:verified.values())if(v.owner().sourceVersion()!=null&&!rights.containsValue(v.owner().sourceVersion()))throw new TenantAccessException(ErrorCode.ACCESS_DENIED);done.addAll(verified.keySet());sourcePins.add(AgentPublicationWitness.tree(verified));
  }if(!done.containsAll(graph.versions().keySet()))bad();
 }
 private void journal(String tenant,String project,String actor,JsonNode r,String action,String event)throws Exception{same(r,json.read(str(one(db.queryForList("SELECT resource_ref FROM audit_event WHERE tenant_id=? AND project_id=? AND audit_id=? AND subject_id=? AND action=? AND result='SUCCESS' LIMIT 2 FOR UPDATE",tenant,project,text(r,"audit_id"),actor,action)),"resource_ref")));same(r,json.read(str(one(db.queryForList("SELECT payload FROM outbox_event WHERE tenant_id=? AND event_id=? AND event_type=? LIMIT 2 FOR UPDATE",tenant,text(r,"event_id"),event)),"payload")));}
 private <T>T tx(ApplicationSessionIdentity.Verified s,Work<T> w){return access.execute(s,a->ThrowingSupplier.of(()->w.run(a)).get());}private interface Work<T>{T run(EnterpriseAccess.Admission a)throws Exception;}
